<?php

declare(strict_types=1);

namespace KclLib\Tests;

use Com\Kcl\Api\Decorator;
use Com\Kcl\Api\Example;
use Com\Kcl\Api\FunctionType;
use Com\Kcl\Api\IndexSignature;
use Com\Kcl\Api\KclType;
use Com\Kcl\Api\Parameter;
use Google\Protobuf\Internal\MapField;
use Google\Protobuf\Internal\RepeatedField;
use KclLib\KclException;
use KclLib\ServiceClient;
use PHPUnit\Framework\TestCase;

/**
 * Cross-language consistency runner: executes the hermetic cases from
 * tests/consistency/cases.json (generated by tests/consistency/generate_cases.py)
 * and asserts the same golden expectations as the lua/dart/python/go/java/
 * dotnet runners. Nothing about a case is hardcoded here — the name, the
 * arguments and the expected values all come from the shared manifest, and
 * the projections below only say how to read an answer out of the decoded
 * protobuf reply, so regenerating the golden file turns a real binding into
 * a real red.
 *
 * Modelled on lua/spec/consistency_spec.lua (the 29-case reference): same
 * per-RPC projections, same default-dialect rendering (`filename` dropped,
 * keys sorted, unset fields absent), same `scratch:` template copies for the
 * cases whose RPCs write files, and the same coverage guard that fails when
 * the manifest grows a case this runner does not dispatch.
 */
final class ConsistencyTest extends TestCase
{
    /** The marker generate_cases.py writes into a path that names a template. */
    private const SCRATCH_PREFIX = 'scratch:';

    private static ?ServiceClient $client = null;
    /** @var array<string, bool>|null */
    private static ?array $methods = null;

    /** @var list<string> scratch roots created by the running case */
    private array $scratchDirs = [];

    public static function setUpBeforeClass(): void
    {
        self::$client = new ServiceClient();
    }

    protected function tearDown(): void
    {
        foreach ($this->scratchDirs as $dir) {
            self::removeTree($dir);
        }
        $this->scratchDirs = [];
    }

    private static function client(): ServiceClient
    {
        return self::$client ??= new ServiceClient();
    }

    private static function repoRoot(): string
    {
        return dirname(__DIR__, 2);
    }

    private static function testdata(): string
    {
        return self::repoRoot() . '/tests/consistency/testdata';
    }

    /** @return array<string, mixed> */
    private static function manifest(): array
    {
        static $manifest = null;
        $manifest ??= json_decode(
            (string) file_get_contents(self::repoRoot() . '/tests/consistency/cases.json'),
            true,
            512,
            JSON_THROW_ON_ERROR
        );

        return $manifest;
    }

    /** @return array<string, mixed> */
    private static function findCase(string $name): array
    {
        foreach (self::manifest()['cases'] as $case) {
            if ($case['name'] === $name) {
                return $case;
            }
        }
        throw new \RuntimeException("consistency case not found in manifest: {$name}");
    }

    /**
     * The RPC surface of the core this binding is linked against, as a set,
     * resolved once per run. Cores that predate `BuiltinService.ListMethod`
     * answer with an empty list or raise; either way `new_core` cases are
     * skipped rather than failed.
     *
     * @return array<string, bool>
     */
    private static function methods(): array
    {
        if (self::$methods !== null) {
            return self::$methods;
        }
        $set = [];
        try {
            $result = self::client()->listMethod();
            foreach ($result->getMethodNameList() as $name) {
                $set[$name] = true;
            }
        } catch (KclException) {
            // old core: every new_core case below skips
        }
        self::$methods = $set;

        return $set;
    }

    // ------------------------------------------------------------------
    // Path handling: repo-relative entries resolve against the repository
    // root, absolute entries are kept, and `scratch:` names a per-case copy
    // of a testdata template so the RPCs that write files never touch the
    // repository.
    // ------------------------------------------------------------------

    private static function isAbsolute(string $path): bool
    {
        return str_starts_with($path, '/')
            || str_starts_with($path, '\\')
            || preg_match('/^[A-Za-z]:[\/\\\\]/', $path) === 1;
    }

    /** Split on both separators: the suite runs on Windows CI too. */
    private static function basename(string $path): string
    {
        return basename(str_replace('\\', '/', $path));
    }

    /** @param list<string> $values @return list<string> */
    private static function sortedBasenames(iterable $values): array
    {
        $out = [];
        foreach ($values as $value) {
            $out[] = self::basename((string) $value);
        }
        sort($out);

        return $out;
    }

    private static function removeTree(string $path): void
    {
        if (!is_dir($path)) {
            @unlink($path);
            return;
        }
        foreach (scandir($path) ?: [] as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            self::removeTree($path . '/' . $entry);
        }
        rmdir($path);
    }

    private static function copyTree(string $src, string $dest): void
    {
        if (!is_dir($dest) && !mkdir($dest, 0700, true) && !is_dir($dest)) {
            throw new \RuntimeException("failed to create scratch directory {$dest}");
        }
        foreach (scandir($src) ?: [] as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            $from = $src . '/' . $entry;
            $to = $dest . '/' . $entry;
            if (is_dir($from)) {
                self::copyTree($from, $to);
            } else {
                // A real copy rather than a hard link: OverrideFile writes
                // through the path it is handed, and a link would send that
                // write back into the repository.
                if (copy($from, $to) === false) {
                    throw new \RuntimeException("failed to copy {$from} to {$to}");
                }
            }
        }
    }

    /**
     * Copy `testdata/<template>` and return the path of `tail` inside the
     * copy. Each call gets its own directory, so two cases — and two runs —
     * never observe each other's writes. A case naming the same template
     * twice (`load_settings_files` names one in both `work_dir` and `files`)
     * gets two copies, exactly as the other runners do.
     */
    private function scratch(string $rest): string
    {
        $slash = strpos($rest, '/');
        if ($slash === false) {
            $template = $rest;
            $tail = '';
        } else {
            $template = substr($rest, 0, $slash);
            $tail = substr($rest, $slash + 1);
        }
        $src = self::testdata() . '/' . $template;
        if (!is_dir($src)) {
            throw new \RuntimeException("scratch template is not a directory: {$src}");
        }
        $root = sys_get_temp_dir() . '/kcl-php-consistency-' . bin2hex(random_bytes(8));
        if (!mkdir($root, 0700, true) && !is_dir($root)) {
            throw new \RuntimeException("failed to create scratch directory {$root}");
        }
        $this->scratchDirs[] = $root;
        $dest = $root . '/' . $template;
        self::copyTree($src, $dest);

        return $tail !== '' ? $dest . '/' . $tail : $dest;
    }

    private function resolvePath(string $path): string
    {
        if (str_starts_with($path, self::SCRATCH_PREFIX)) {
            return $this->scratch(substr($path, strlen(self::SCRATCH_PREFIX)));
        }
        if (self::isAbsolute($path)) {
            return $path;
        }

        return self::repoRoot() . '/' . $path;
    }

    /** @param list<string> $values @return list<string> */
    private function resolvePaths(array $values): array
    {
        $out = [];
        foreach ($values as $value) {
            $out[] = $this->resolvePath($value);
        }

        return $out;
    }

    // ------------------------------------------------------------------
    // Request builders, mirroring the lua runner field for field.
    // ------------------------------------------------------------------

    /** @return array<string, mixed> */
    private function parseArgs(array $node): array
    {
        $args = [];
        $paths = $this->resolvePaths($node['paths'] ?? []);
        if ($paths !== []) {
            $args['paths'] = $paths;
        }
        if (isset($node['sources'])) {
            $args['sources'] = $node['sources'];
        }
        if (isset($node['external_pkgs'])) {
            $args['external_pkgs'] = $node['external_pkgs'];
        }

        return $args;
    }

    /**
     * Build `ExecProgramArgs` from the manifest. The manifest spells out
     * every proto3 field, but the unset ones carry their proto defaults, so
     * only the fields that actually drive the case are forwarded.
     *
     * `k_filename_list` is resolved by the core against the process working
     * directory rather than against `work_dir`, so a relative entry has to
     * be made absolute here or it will not survive being run from another
     * directory.
     *
     * @return array<string, mixed>
     */
    private function execArgs(array $node): array
    {
        $args = [];
        $workDir = $node['work_dir'] ?? null;
        $resolvedDir = $workDir !== null ? $this->resolvePath($workDir) : '.';
        foreach ([
            'k_code_list', 'overrides', 'disable_yaml_result', 'print_override_ast',
            'strict_range_check', 'disable_none', 'sort_keys', 'include_schema_type_path',
            'compile_only', 'show_hidden', 'path_selector', 'fast_eval', 'error_format',
            'format', 'emit_attribute_metadata', 'verbose', 'debug',
        ] as $key) {
            $value = $node[$key] ?? null;
            if ($value !== null && $value !== '') {
                $args[$key] = $value;
            }
        }
        if ($workDir !== null) {
            $args['work_dir'] = $resolvedDir;
        }
        $filenames = $node['k_filename_list'] ?? null;
        if ($filenames !== null && $filenames !== []) {
            $resolved = [];
            foreach ($filenames as $name) {
                $resolved[] = self::isAbsolute($name) ? $name : $resolvedDir . '/' . $name;
            }
            $args['k_filename_list'] = $resolved;
        }
        // `args` is a `repeated Argument`, not a `repeated string`.
        $arguments = [];
        foreach ($node['args'] ?? [] as $spec) {
            if (preg_match('/^([^=]*)=(.*)$/s', (string) $spec, $m) === 1) {
                $arguments[] = ['name' => $m[1], 'value' => $m[2]];
            }
        }
        if ($arguments !== []) {
            $args['args'] = $arguments;
        }
        if (($node['external_pkgs'] ?? []) !== []) {
            $args['external_pkgs'] = $node['external_pkgs'];
        }

        return $args;
    }

    /**
     * `ParseFileArgs`. Unlike `ParseProgramArgs.paths`, `path` is a label
     * the AST records rather than a file to read — `source` carries the
     * program — so it is forwarded verbatim.
     *
     * @return array<string, mixed>
     */
    private function parseFileArgs(array $node): array
    {
        $args = [
            'path' => $node['path'] ?? '',
            'source' => $node['source'] ?? '',
        ];
        if (($node['external_pkgs'] ?? []) !== []) {
            $args['external_pkgs'] = $node['external_pkgs'];
        }

        return $args;
    }

    /** @return array<string, mixed> */
    private function validateArgs(array $node): array
    {
        $args = [];
        foreach (['code', 'data', 'datafile', 'file', 'schema', 'attribute_name', 'format'] as $key) {
            $value = $node[$key] ?? null;
            if ($value !== null && $value !== '') {
                $args[$key] = $value;
            }
        }
        if (($node['external_pkgs'] ?? []) !== []) {
            $args['external_pkgs'] = $node['external_pkgs'];
        }

        return $args;
    }

    /** @return array<string, mixed> */
    private function schemaArgs(array $node): array
    {
        return [
            'exec_args' => $this->execArgs($node['exec_args'] ?? []),
            'schema_name' => $node['schema_name'] ?? '',
        ];
    }

    // ------------------------------------------------------------------
    // Canonical rendering: both sides of every comparison go through one
    // definition of the canonical form. Object keys are sorted and the
    // `filename` key dropped (a KclType carries absolute paths that differ
    // on every machine); an empty array renders as `{}`, which is what an
    // empty array and an empty object both decode to on the manifest side.
    // ------------------------------------------------------------------

    private static function canonicalJson(mixed $value): string
    {
        if (!is_array($value)) {
            if (is_bool($value)) {
                return $value ? 'true' : 'false';
            }
            if (is_int($value)) {
                return (string) $value;
            }
            if (is_float($value)) {
                return floor($value) === $value.'' ? (string) (int) $value : (string) $value;
            }
            if ($value === null) {
                return 'null';
            }

            return (string) json_encode($value, JSON_UNESCAPED_SLASHES);
        }
        if ($value !== [] && array_is_list($value)) {
            $items = [];
            foreach ($value as $item) {
                $items[] = self::canonicalJson($item);
            }

            return '[' . implode(',', $items) . ']';
        }
        $keys = array_keys($value);
        sort($keys);
        $parts = [];
        foreach ($keys as $key) {
            if ($key === 'filename') {
                continue;
            }
            $parts[] = (string) json_encode((string) $key) . ':' . self::canonicalJson($value[$key]);
        }

        return '{' . implode(',', $parts) . '}';
    }

    /**
     * The rendering a pinned field is compared through. A top-level string
     * stays raw: the generated documents are dozens of lines long, and the
     * mismatch report diffs them line by line.
     */
    private static function render(mixed $value): string
    {
        if (is_string($value)) {
            return $value;
        }

        return self::canonicalJson($value);
    }

    /** @return list<string> */
    private static function splitLines(string $text): array
    {
        return explode("\n", $text . "\n");
    }

    /** Line-wise `--- expected / +++ actual` rendering, mirroring the other runners. */
    private static function diffLines(string $expected, string $actual): string
    {
        $want = self::splitLines($expected);
        $got = self::splitLines($actual);
        $out = ['--- expected', '+++ actual'];
        $n = max(count($want), count($got));
        for ($i = 0; $i < $n; $i++) {
            $e = $want[$i] ?? null;
            $a = $got[$i] ?? null;
            if ($e === $a) {
                $out[] = '  ' . $e;
            } else {
                if ($e !== null) {
                    $out[] = '- ' . $e;
                }
                if ($a !== null) {
                    $out[] = '+ ' . $a;
                }
            }
        }

        return implode("\n", $out);
    }

    // ------------------------------------------------------------------
    // Projections: a KclType as canonical protobuf JSON in the default
    // dialect, so a field the core left unset is absent rather than rendered
    // as an empty value — the golden file is the default dialect too.
    // ------------------------------------------------------------------

    /** @return array<string, mixed> */
    private static function kclTypeJson(?KclType $ty): array
    {
        $out = [];
        if ($ty === null) {
            return $out;
        }
        foreach ([
            'type' => $ty->getType(),
            'schema_name' => $ty->getSchemaName(),
            'schema_doc' => $ty->getSchemaDoc(),
            'default' => $ty->getDefault(),
            'pkg_path' => $ty->getPkgPath(),
            'description' => $ty->getDescription(),
        ] as $key => $value) {
            if ($value !== '') {
                $out[$key] = $value;
            }
        }
        // `filename` is emitted here and dropped by `canonicalJson`, so there
        // is exactly one place that decides an unpinnable field is dropped.
        if ($ty->getFilename() !== '') {
            $out['filename'] = $ty->getFilename();
        }
        if ($ty->getLine() !== 0) {
            $out['line'] = $ty->getLine();
        }
        if ($ty->getRequired()->count() > 0) {
            $out['required'] = iterator_to_array($ty->getRequired());
        }
        if ($ty->getUnionTypes()->count() > 0) {
            $items = [];
            foreach ($ty->getUnionTypes() as $child) {
                $items[] = self::kclTypeJson($child);
            }
            $out['union_types'] = $items;
        }
        if ($ty->getProperties()->count() > 0) {
            $map = [];
            foreach ($ty->getProperties() as $name => $child) {
                $map[$name] = self::kclTypeJson($child);
            }
            $out['properties'] = $map;
        }
        if ($ty->getExamples()->count() > 0) {
            $map = [];
            foreach ($ty->getExamples() as $name => $example) {
                $map[$name] = self::exampleJson($example);
            }
            $out['examples'] = $map;
        }
        if ($ty->getDecorators()->count() > 0) {
            $items = [];
            foreach ($ty->getDecorators() as $decorator) {
                $items[] = self::decoratorJson($decorator);
            }
            $out['decorators'] = $items;
        }
        if ($ty->getKey() !== null) {
            $out['key'] = self::kclTypeJson($ty->getKey());
        }
        if ($ty->getItem() !== null) {
            $out['item'] = self::kclTypeJson($ty->getItem());
        }
        if ($ty->getBaseSchema() !== null) {
            $out['base_schema'] = self::kclTypeJson($ty->getBaseSchema());
        }
        $function = $ty->getFunction();
        if ($function !== null) {
            $out['function'] = self::functionTypeJson($function);
        }
        $signature = $ty->getIndexSignature();
        if ($signature !== null) {
            $out['index_signature'] = self::indexSignatureJson($signature);
        }

        return $out;
    }

    /** @return array<string, mixed> */
    private static function exampleJson(Example $example): array
    {
        $out = [];
        foreach (['summary' => $example->getSummary(), 'description' => $example->getDescription(), 'value' => $example->getValue()] as $key => $value) {
            if ($value !== '') {
                $out[$key] = $value;
            }
        }

        return $out;
    }

    /** @return array<string, mixed> */
    private static function decoratorJson(Decorator $decorator): array
    {
        $out = [];
        if ($decorator->getName() !== '') {
            $out['name'] = $decorator->getName();
        }
        if ($decorator->getArguments()->count() > 0) {
            $out['arguments'] = iterator_to_array($decorator->getArguments());
        }
        if ($decorator->getKeywords()->count() > 0) {
            $out['keywords'] = iterator_to_array($decorator->getKeywords());
        }

        return $out;
    }

    /** @return array<string, mixed> */
    private static function functionTypeJson(FunctionType $function): array
    {
        $out = [];
        if ($function->getParams()->count() > 0) {
            $items = [];
            foreach ($function->getParams() as $param) {
                $items[] = self::parameterJson($param);
            }
            $out['params'] = $items;
        }
        if ($function->getReturnTy() !== null) {
            $out['return_ty'] = self::kclTypeJson($function->getReturnTy());
        }

        return $out;
    }

    /** @return array<string, mixed> */
    private static function parameterJson(Parameter $param): array
    {
        $out = [];
        if ($param->getName() !== '') {
            $out['name'] = $param->getName();
        }
        if ($param->getTy() !== null) {
            $out['ty'] = self::kclTypeJson($param->getTy());
        }

        return $out;
    }

    /** @return array<string, mixed> */
    private static function indexSignatureJson(IndexSignature $signature): array
    {
        $out = [];
        if ($signature->getKeyName() !== '') {
            $out['key_name'] = $signature->getKeyName();
        }
        if ($signature->getKey() !== null) {
            $out['key'] = self::kclTypeJson($signature->getKey());
        }
        if ($signature->getVal() !== null) {
            $out['val'] = self::kclTypeJson($signature->getVal());
        }
        if ($signature->getAnyOther()) {
            $out['any_other'] = true;
        }

        return $out;
    }

    /**
     * `GetSchemaTypeMappingUnderPath` answers a `SchemaTypes` document — a
     * `schema_type` array rather than the flat map the plain RPC returns —
     * so the two cases serialise through different shapes even though the
     * runner pins both under `type_mapping`.
     *
     * @return array<string, mixed>
     */
    private static function schemaTypesJson(object $types): array
    {
        $out = ['schema_type' => []];
        foreach ($types->getSchemaType() as $ty) {
            $out['schema_type'][] = self::kclTypeJson($ty);
        }

        return $out;
    }

    // ------------------------------------------------------------------
    // Counting helpers for the shape-and-count cases.
    // ------------------------------------------------------------------

    /** Count the entries of a `repeated` or `map` protobuf field. */
    private static function countField(RepeatedField|MapField $field): int
    {
        return $field->count();
    }

    /**
     * Count the entries of `key` (optionally `key.subkey`) in a JSON document,
     * treating an empty or unparsable document as zero. `ParseFile` answers a
     * bare `Module` — the statements are at `body` — while `ParseProgram`
     * answers a `pkgs` document keyed by package path.
     */
    private static function countArray(string $doc, string $key, ?string $subkey = null): int
    {
        if ($doc === '') {
            return 0;
        }
        $decoded = json_decode($doc, true);
        if (!is_array($decoded)) {
            return 0;
        }
        $node = $decoded[$key] ?? null;
        if ($subkey !== null) {
            $node = is_array($node) ? ($node[$subkey] ?? null) : null;
        }
        if (!is_array($node)) {
            return 0;
        }
        // `pkgs.__main__` is a list; a bare `body` is a list too. A wrong
        // shape (e.g. the module object itself) must not read as a count.
        return count($node);
    }

    /**
     * A `[[a, b], ...]` list of pairs, sorted on the first element. The order
     * the core answers with is not pinnable — a protobuf map's iteration order
     * is undefined — so the manifest pins these as a set.
     *
     * @param list<array{0: string, 1: mixed}> $pairs
     * @return list<array{0: string, 1: mixed}>
     */
    private static function sortPairs(array $pairs): array
    {
        usort($pairs, static fn (array $a, array $b): int => $a[0] <=> $b[0]);

        return $pairs;
    }

    // ------------------------------------------------------------------
    // Dispatch: one projection per RPC, mirroring the `extract` of each
    // definition in tests/consistency/generate_cases.py.
    // ------------------------------------------------------------------

    /** @return array<string, callable(array<string, mixed>): array<string, mixed>> */
    private function dispatch(): array
    {
        $client = self::client();

        return [
            'KclService.Ping' => static fn (array $case): array => [
                'value' => $client->ping(['value' => $case['args']['value'] ?? ''])->getValue(),
            ],
            'KclService.ExecProgram' => function (array $case) use ($client): array {
                $result = $client->execProgram($this->execArgs($case['args']));
                return [
                    'yaml_result' => $result->getYamlResult(),
                    'json_result' => $result->getJsonResult(),
                ];
            },
            'KclService.FormatCode' => static fn (array $case): array => [
                'formatted' => $client->formatCode(['source' => $case['args']['source'] ?? ''])->getFormatted(),
            ],
            'KclService.ValidateCode' => function (array $case) use ($client): array {
                $result = $client->validateCode($this->validateArgs($case['args']));
                return [
                    'success' => $result->getSuccess(),
                    // The diagnostic carries ANSI colour escapes, a random temp
                    // path and a temp filename, so the string itself is not
                    // pinnable but its presence is. `err_message` is emitted
                    // for both cases so `validate_code_ok`, which pins it as
                    // the empty string, still finds the field the manifest
                    // names.
                    'has_error_message' => $result->getErrMessage() !== '',
                    'err_message' => $result->getErrMessage(),
                ];
            },
            'KclService.FormatTestReport' => static fn (array $case): array => [
                'report' => $client->formatTestReport(['result' => $case['args']['result'] ?? []])->getReport(),
            ],
            'KclService.GenerateToml' => fn (array $case): array => [
                'toml' => $client->generateToml([
                    'exec_args' => $this->execArgs($case['args']['exec_args'] ?? []),
                    'sort_keys' => $case['args']['sort_keys'] ?? false,
                ])->getToml(),
            ],
            'KclService.GenerateKcl' => static fn (array $case): array => [
                'kcl' => $client->generateKcl([
                    'source' => $case['args']['source'] ?? '',
                    'filename' => $case['args']['filename'] ?? '',
                    'format' => $case['args']['format'] ?? '',
                ])->getKcl(),
            ],
            'KclService.GenerateOpenAPI' => fn (array $case): array => [
                'spec' => $client->generateOpenAPI([
                    'parse_args' => $this->parseArgs($case['args']['parse_args'] ?? []),
                    'version' => $case['args']['version'] ?? '',
                ])->getSpec(),
            ],
            'KclService.GenerateProto' => fn (array $case): array => [
                'proto' => $client->generateProto([
                    'parse_args' => $this->parseArgs($case['args']['parse_args'] ?? []),
                    'package' => $case['args']['package'] ?? '',
                ])->getProto(),
            ],
            'KclService.GenerateDoc' => fn (array $case): array => [
                'content' => $client->generateDoc([
                    'parse_args' => $this->parseArgs($case['args']['parse_args'] ?? []),
                    'format' => $case['args']['format'] ?? '',
                ])->getContent(),
            ],
            'KclService.ParseFile' => function (array $case) use ($client): array {
                $result = $client->parseFile($this->parseFileArgs($case['args']));
                return [
                    // A bare `Module` document, so the statements are at `body`.
                    'body_count' => self::countArray($result->getAstJson(), 'body'),
                    'error_count' => self::countField($result->getErrors()),
                    'deps' => iterator_to_array($result->getDeps()),
                ];
            },
            'KclService.ParseProgram' => function (array $case) use ($client): array {
                $result = $client->parseProgram($this->parseArgs($case['args']));
                return [
                    // `ParseProgram` returns a `pkgs` document, not a module: one
                    // Module per file, keyed by package path.
                    'module_count' => self::countArray($result->getAstJson(), 'pkgs', '__main__'),
                    'error_count' => self::countField($result->getErrors()),
                    'paths' => self::sortedBasenames($result->getPaths()),
                ];
            },
            'KclService.ListOptions' => function (array $case) use ($client): array {
                $result = $client->listOptions($this->parseArgs($case['args']));
                $options = [];
                foreach ($result->getOptions() as $option) {
                    $options[] = [$option->getName(), $option->getRequired()];
                }
                return [
                    'option_count' => self::countField($result->getOptions()),
                    'options' => self::sortPairs($options),
                ];
            },
            'KclService.ListVariables' => function (array $case) use ($client): array {
                $args = $case['args'];
                $result = $client->listVariables([
                    'files' => $this->resolvePaths($args['files'] ?? []),
                    'specs' => $args['specs'] ?? [],
                    'options' => ['merge_program' => $args['options']['merge_program'] ?? false],
                ]);
                $values = [];
                foreach ($result->getVariables() as $spec => $list) {
                    $items = [];
                    foreach ($list->getVariables() as $variable) {
                        $items[] = $variable->getValue();
                    }
                    $values[$spec] = $items;
                }
                return [
                    'values' => $values,
                    'unsupported_codes' => iterator_to_array($result->getUnsupportedCodes()),
                    'parse_error_count' => self::countField($result->getParseErrors()),
                ];
            },
            'KclService.LoadPackage' => function (array $case) use ($client): array {
                $args = $case['args'];
                $result = $client->loadPackage([
                    'parse_args' => $this->parseArgs($args['parse_args'] ?? []),
                    'resolve_ast' => $args['resolve_ast'] ?? false,
                    'load_builtin' => $args['load_builtin'] ?? false,
                    'with_ast_index' => $args['with_ast_index'] ?? false,
                ]);
                $mod = $result->getKclMod();
                return [
                    'path_count' => self::countField($result->getPaths()),
                    'type_error_count' => self::countField($result->getTypeErrors()),
                    'parse_error_count' => self::countField($result->getParseErrors()),
                    'symbol_count' => self::countField($result->getSymbols()),
                    'scope_count' => self::countField($result->getScopes()),
                    'has_kcl_mod' => $mod !== null,
                    'kcl_mod_name' => $mod !== null ? $mod->getPackage()->getName() : '',
                    'app_count' => self::countField($result->getApps()),
                    'import_count' => self::countField($result->getImports()),
                ];
            },
            'KclService.GetSchemaTypeMapping' => function (array $case) use ($client): array {
                $result = $client->getSchemaTypeMapping($this->schemaArgs($case['args']));
                $mapping = [];
                foreach ($result->getSchemaTypeMapping() as $name => $ty) {
                    $mapping[$name] = self::kclTypeJson($ty);
                }
                return ['type_mapping' => $mapping];
            },
            'KclService.GetSchemaTypeMappingUnderPath' => function (array $case) use ($client): array {
                $result = $client->getSchemaTypeMappingUnderPath($this->schemaArgs($case['args']));
                $mapping = [];
                foreach ($result->getSchemaTypeMapping() as $name => $types) {
                    $mapping[$name] = self::schemaTypesJson($types);
                }
                return ['type_mapping' => $mapping];
            },
            'KclService.GetVersion' => static function () use ($client): array {
                $result = $client->getVersion();
                // Only the major.minor pair is pinned: the patch moves with
                // every release, and the manifest is regenerated against a
                // pinned core.
                $parts = explode('.', $result->getVersion());
                $version = count($parts) >= 2 ? $parts[0] . '.' . $parts[1] : $result->getVersion();
                return [
                    'version' => $version,
                    'has_checksum' => $result->getChecksum() !== '',
                    'has_git_sha' => $result->getGitSha() !== '',
                    'has_version_info' => $result->getVersionInfo() !== '',
                ];
            },
            'BuiltinService.ListMethod' => static function () use ($client): array {
                $names = iterator_to_array($client->listMethod()->getMethodNameList());
                $listed = array_fill_keys($names, true);
                return [
                    'has_kclservice_ping' => isset($listed['KclService.Ping']),
                    'has_kclservice_parse_program' => isset($listed['KclService.ParseProgram']),
                    'has_builtinservice_list_method' => isset($listed['BuiltinService.ListMethod']),
                    'method_count' => count($names),
                    'has_empty_name' => in_array('', $names, true),
                ];
            },
            'KclService.LintPath' => function (array $case) use ($client): array {
                $result = $client->lintPath(['paths' => $this->resolvePaths($case['args']['paths'] ?? [])]);
                return [
                    'result_count' => self::countField($result->getResults()),
                    'has_result' => self::countField($result->getResults()) > 0,
                ];
            },
            'KclService.FormatPath' => function (array $case) use ($client): array {
                $result = $client->formatPath([
                    'path' => $this->resolvePath($case['args']['path'] ?? ''),
                    'dry_run' => $case['args']['dry_run'] ?? false,
                ]);
                return [
                    'changed_count' => self::countField($result->getChangedPaths()),
                    'changed' => self::sortedBasenames($result->getChangedPaths()),
                ];
            },
            'KclService.Test' => function (array $case) use ($client): array {
                $result = $client->test([
                    'exec_args' => $this->execArgs($case['args']['exec_args'] ?? []),
                    'pkg_list' => $this->resolvePaths($case['args']['pkg_list'] ?? []),
                    'run_regexp' => $case['args']['run_regexp'] ?? '',
                    'fail_fast' => $case['args']['fail_fast'] ?? false,
                    'coverage' => $case['args']['coverage'] ?? false,
                ]);
                return [
                    'names' => self::sortedList($result->getInfo(), 'getName'),
                    'failed' => self::sortedFailed($result->getInfo()),
                ];
            },
            'KclService.OverrideFile' => function (array $case) use ($client): array {
                $result = $client->overrideFile([
                    'file' => $this->resolvePath($case['args']['file'] ?? ''),
                    'specs' => $case['args']['specs'] ?? [],
                    'import_paths' => $this->resolvePaths($case['args']['import_paths'] ?? []),
                ]);
                return [
                    'result' => $result->getResult(),
                    'parse_error_count' => self::countField($result->getParseErrors()),
                ];
            },
            'KclService.LoadSettingsFiles' => function (array $case) use ($client): array {
                $result = $client->loadSettingsFiles([
                    'work_dir' => $this->resolvePath($case['args']['work_dir'] ?? ''),
                    'files' => $this->resolvePaths($case['args']['files'] ?? []),
                ]);
                $options = [];
                foreach ($result->getKclOptions() as $option) {
                    $options[] = [$option->getKey(), $option->getValue()];
                }
                $out = ['options' => self::sortPairs($options)];
                $config = $result->getKclCliConfigs();
                if ($config !== null) {
                    $out['output'] = $config->getOutput();
                    $out['overrides'] = iterator_to_array($config->getOverrides());
                    $out['strict_range_check'] = $config->getStrictRangeCheck();
                    $out['verbose'] = $config->getVerbose();
                }
                return $out;
            },
            'KclService.UpdateDependencies' => fn (array $case): array => [
                'external_pkg_count' => self::countField($client->updateDependencies([
                    'manifest_path' => $this->resolvePath($case['args']['manifest_path'] ?? ''),
                    'vendor' => $case['args']['vendor'] ?? false,
                ])->getExternalPkgs()),
            ],
        ];
    }

    /** @param iterable<object> $info @return list<string> */
    private static function sortedList(iterable $info, string $getter): array
    {
        $out = [];
        foreach ($info as $item) {
            $out[] = $item->{$getter}();
        }
        sort($out);

        return $out;
    }

    /** @param iterable<object> $info @return list<string> */
    private static function sortedFailed(iterable $info): array
    {
        $out = [];
        foreach ($info as $item) {
            if ($item->getError() !== '') {
                $out[] = $item->getName();
            }
        }
        sort($out);

        return $out;
    }

    /**
     * Run one manifest case: dispatch on `rpc`, then compare every field
     * that `expect` actually mentions. Unknown RPCs are a hard failure, a
     * missing RPC on an old core is a skip.
     */
    private function assertCase(string $name): void
    {
        $case = self::findCase($name);
        $rpc = $case['rpc'];
        $dispatch = $this->dispatch();
        $this->assertArrayHasKey($rpc, $dispatch, "no runner support for rpc {$rpc}");

        if (($case['new_core'] ?? false) && !isset(self::methods()[$rpc])) {
            $this->markTestSkipped("core does not list {$rpc} (old core)");
        }

        $actual = $dispatch[$rpc]($case);
        $expect = $case['expect'];
        ksort($expect);
        $this->assertNotEmpty($expect, "consistency case `{$name}` pins no fields");
        foreach ($expect as $key => $wanted) {
            // Only the fields the manifest pins are compared, so adding a
            // field to `expect` is the only way to start asserting on it. A
            // pinned field the projection does not produce is a failure
            // rather than a skip, because the key is missing from the
            // projection either way.
            $this->assertArrayHasKey(
                $key,
                $actual,
                "consistency case `{$name}` expects field `{$key}`, which the projection does not produce"
            );
            $want = self::render($wanted);
            $got = self::render($actual[$key]);
            $this->assertSame(
                $want,
                $got,
                "consistency case `{$name}` field `{$key}` mismatch\n" . self::diffLines($want, $got)
            );
        }
    }

