    /**
     * Every case in `tests/consistency/cases.json` must be dispatched by one
     * of the tests above. Without this a runner that covers half the spec
     * passes silently — which is exactly how the manifest could grow from
     * 13 cases to 29 while a 13-case runner still reported green. The check
     * reads the test list above rather than anything the suite recorded at
     * run time, so it cannot agree with itself.
     */
    public function testDispatchesEveryCaseInTheManifest(): void
    {
        $dispatched = [
            'ping', 'exec_program_basic', 'exec_program_overrides', 'format_code',
            'validate_code_ok', 'validate_code_invalid', 'generate_kcl_json',
            'generate_kcl_yaml', 'generate_toml', 'format_test_report',
            'generate_openapi_v3', 'generate_proto', 'generate_doc_md',
            'parse_file', 'parse_program', 'list_options', 'list_variables',
            'load_package', 'get_schema_type_mapping',
            'get_schema_type_mapping_under_path', 'get_version', 'list_method',
            'lint_path_clean', 'lint_path_with_errors', 'format_path_dry_run',
            'test_run', 'override_file', 'load_settings_files',
            'update_dependencies_no_deps',
        ];
        $missing = [];
        foreach (self::manifest()['cases'] as $case) {
            if (!in_array($case['name'], $dispatched, true)) {
                $missing[] = $case['name'];
            }
        }
        sort($missing);
        $this->assertCount(29, self::manifest()['cases']);
        $this->assertSame(
            [],
            $missing,
            'cases.json has cases this runner does not dispatch; add a test for each'
        );
    }
